function save() {
  try { localStorage.setItem(storageKey, JSON.stringify(completed)); storageAvailable = true; }
  catch { storageAvailable = false; }
}
const draftPrefix='csquest-draft-v1:';
function readDraft(id,restore,fresh) {
  try { const raw=localStorage.getItem(draftPrefix+id); return raw===null?fresh():restore(JSON.parse(raw)); }
  catch { draftIssue=true;return fresh(); }
}
function writeDraft(id,data) {
  try { localStorage.setItem(draftPrefix+id,JSON.stringify(data)); draftIssue=false; }
  catch { draftIssue=true; }
}
function clearDraft(id) {
  try { localStorage.removeItem(draftPrefix+id); draftIssue=false; }
  catch { draftIssue=true; }
}
function scheduleDraft() {
  return {selected:schedulePolicy,fcfs:scheduleStates.fcfs.history,rr:scheduleStates.rr.history};
}
function draftMessage() {
  return `${draftIssue?'<p class="storage-warning draft-note" role="status">途中記録を読み込めないか、保存できませんでした。保存データやブラウザの設定を確認してください。</p>':'<p class="draft-note">この依頼の途中経過は、このブラウザに保存されます。</p>'}<button id="reset-draft" class="text-link">途中経過を消して最初から ↺</button>`;
}
