  const region = findRegion(selectedRegion);
  const story = storyProgress(completed);
  app.innerHTML = `<section class="hero"><div class="hero-copy"><div class="eyebrow"><span></span> A LITTLE ADVENTURE IN COMPUTER SCIENCE</div><p class="chapter">はじまりの地域 ／ 精霊の工房</p><h1>ひらめきが、<br><em>道をひらく。</em></h1><p class="intro">不思議な依頼が届く冒険者ギルド。<br>精霊たちと手を取り、世界のしくみを解き明かそう。</p><a href="#quests" class="primary hero-button">依頼を見に行く <span>↗</span></a><p class="hero-note">✧　知識は、冒険の道具になる。</p></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="moon"></div><div class="spark spark-a">✦</div><div class="spark spark-b">✧</div><div class="spark spark-c">✧</div><div class="tower"><div class="roof"></div><div class="tower-body"><i></i><i></i><i></i><div class="tower-door"></div></div></div><div class="ground"></div><div class="art-caption">THE SPIRIT WORKSHOP<br><span>精霊の工房</span></div></div></section><section id="quests" class="quests"><div class="section-head"><div><div class="eyebrow"><span></span> QUEST BOARD</div><h2>ギルドの依頼</h2><p>気になる依頼から始めよう。はじめてなら 01 からがおすすめ。</p></div><div class="progress"><span>冒険の記録</span><strong>${finished}<small> / ${allLevels.length}</small></strong><span>依頼を達成</span></div></div><section class="story-panel" aria-labelledby="story-heading"><div class="story-header"><div><div class="eyebrow"><span></span> THE BEACON OF THE GUILD</div><h3 id="story-heading">塔の灯りと八つの知らせ</h3></div><div class="story-count"><strong>${story.visited.length} / ${regions.length}</strong><span>知らせが届いた場所</span></div></div><div class="story-dialogue" aria-live="polite"><div class="story-portrait" aria-hidden="true">${story.current.speaker.includes('ノノ')?'✧':'⚑'}</div><div><span class="story-speaker">${story.current.speaker} ／ ${story.current.title}</span><p>「${story.current.text}」</p></div></div><p class="story-next">${story.next?`次の知らせまで、別の場所の依頼をあと ${story.next.threshold-story.visited.length} つ達成しましょう。どの依頼からでも進められます。`:'各地からの知らせで、塔の灯りが再び輝きました。'}</p><details class="story-history"><summary>これまでの物語を読む（${story.scenes.length}）</summary>${story.scenes.map(scene=>`<section><h4>${scene.title}</h4><p><strong>${scene.speaker}</strong>「${scene.text}」</p></section>`).join('')}</details>${!storageAvailable?'<p class="storage-warning world-warning" role="status">冒険の記録を保存できませんでした。ブラウザの保存設定を確認してください。</p>':''}</section>${renderTrail()}<div class="world-panel"><div class="world-heading"><div><div class="eyebrow"><span></span> THE ADVENTURER’S MAP</div><h3>世界を巡ろう</h3><p>地図から行き先を選ぶと、その場所の依頼が並びます。順番に決まりはありません。</p></div><button class="world-all" data-region="all" aria-pressed="${selectedRegion==='all'}">すべての依頼を見る</button></div><div class="world-map" role="group" aria-label="行き先を選ぶ"><svg class="world-terrain" viewBox="0 0 800 400" preserveAspectRatio="none" aria-hidden="true"><path class="world-land" d="M-20 70 Q120 5 270 55 T560 50 Q750 30 820 135 L820 340 Q660 390 500 345 T200 350 Q70 395 -20 315 Z"/><path class="world-river" d="M505 -10 C420 90 595 130 510 220 S425 320 505 410"/><path class="world-road" d="M65 95 C190 70 235 155 355 130 S555 50 735 115 M65 275 C225 320 310 195 445 255 S640 315 735 265"/></svg>${regions.map(place=>`<button class="world-place" data-region="${place.id}" aria-pressed="${selectedRegion===place.id}"><span class="world-icon" aria-hidden="true">${place.icon}</span><span><strong>${place.name}</strong><small>${place.quests.filter(id=>completed.includes(id)).length} / ${place.quests.length} 依頼達成${story.visited.includes(place)?' ／ 灯り ✦':''}</small></span></button>`).join('')}</div>${!travelAvailable?'<p class="storage-warning world-warning" role="status">行き先を保存できませんでした。ブラウザの保存設定を確認してください。</p>':''}</div><div class="region-heading" aria-live="polite"><h3>${region?region.name:'すべての依頼'}</h3><p>${region?region.description:'好きな行き先や依頼から冒険を始めましょう。'}</p></div><div class="quest-grid">${visibleQuests(allLevels,selectedRegion).map(({level:l,index:i})=>`<button class="quest-card" data-level="${i}"><span class="card-top"><span>QUEST ${l.number}</span><span>${completed.includes(l.id)?'✓ 達成済み':'未達成'}</span></span><span class="card-icon">${['✦','◇','♜','✧','◈','⌘','⚔','⌖','◇','✉','♜','✿','⌗','◷','✺','⚿','◈','✧'][i] || '✦'}</span><span class="card-tag">${l.tag}を学ぶ</span><strong>${l.name}</strong><span class="card-story">${l.story}</span><span class="card-link">依頼を見る <b>↗</b></span></button>`).join('')}</div><div class="notice"><span>✧</span><p><strong>学びについて</strong><br>依頼では、命令や整列、論理回路などの仕組みを体験します。ゲーム内の操作は、実際のプログラミング言語を書く練習とは異なります。CS2023 のすべての範囲はまだ収録していません。</p></div></section>`;
  app.querySelectorAll('[data-trail]').forEach(button=>button.onclick=()=>{selectedTrail=button.dataset.trail;try{localStorage.setItem(trailKey,selectedTrail);trailAvailable=true;}catch{trailAvailable=false;}renderHome();app.querySelector(`[data-trail="${selectedTrail}"]`).focus();});
