  if(status.done)app.querySelector('#retry-syscall').onclick=()=>{syscallQuest.actions[id]=[];syscallMessage='';writeDraft(active.id,syscallQuest);renderSyscall();app.querySelector('[data-syscall-action]').focus();};
  if(complete)app.querySelector('#return').onclick=renderHome;
