  app.querySelectorAll('[data-chest-field]').forEach(select=>select.onchange=()=>{const key=select.dataset.chestField;choice[key]=select.value===''?null:Number(select.value);choice.tested=false;writeDraft(active.id,expectation);renderExpectation();app.querySelector(`[data-chest-field="${key}"]`).focus();});
  app.querySelector('#check-chest').onclick=()=>{choice.tested=true;writeDraft(active.id,expectation);if(expectationComplete(expectation)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderExpectation();app.querySelector('#check-chest').focus();};
