  app.querySelectorAll('[data-transform]').forEach(select=>select.onchange=()=>{const i=Number(select.dataset.transform);emblem.sequences[id][i]=select.value;emblem.tested[id]=false;writeDraft(active.id,emblem);renderTransform();app.querySelector(`[data-transform="${i}"]`).focus();});
  app.querySelector('#try-transform').onclick=()=>{emblem.tested[id]=true;writeDraft(active.id,emblem);if(transformComplete(emblem)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderTransform();app.querySelector('#try-transform').focus();};
  if(complete)app.querySelector('#return').onclick=renderHome;
