  const show=value=>typeof value==='boolean'?(value?'点灯':'消灯'):String(value);
  app.innerHTML=`<div class="quest-page"><button class="back" id="back">← ギルドに戻る</button><div class="quest-heading"><div><div class="eyebrow"><span></span> QUEST ${active.number} ／ ${active.tag}</div><h1>${active.title}</h1><p>${active.story}</p></div><span class="chapter-badge">魔法の工房 <b>✦</b></span></div><section class="panel circuit-panel"><div class="panel-header"><div><span class="panel-kicker">THE TYPED SPELLS</span><h2>道具を二つつなぐ</h2></div></div>${draftMessage()}<p class="panel-description">入口からは「数」が届き、出口は「灯り」を受け取ります。それぞれの道具が受け取れる種類と、渡す種類を合わせてつなぎましょう。目標は、正の数 3 なら点灯、負の数 -2 なら消灯です。</p><div class="circuit-layout"><div class="circuit-input">入口<br><strong>数</strong></div><span class="circuit-arrow" aria-hidden="true">→</span>${spellQuest.sequence.map((id,i)=>`<label class="gate-choice">道具 ${i+1}<select data-spell="${i}">${Object.entries(spellTools).map(([key,tool])=>`<option value="${key}" ${key===id?'selected':''}>${tool.name}（${typeNames[tool.input]} → ${typeNames[tool.output]}）</option>`).join('')}</select><small>受け取る：${typeNames[spellTools[id].input]} ／ 渡す：${typeNames[spellTools[id].output]}</small></label>${i===0?'<span class="circuit-arrow" aria-hidden="true">→</span>':''}`).join('')}<span class="circuit-arrow" aria-hidden="true">→</span><div class="circuit-input">出口<br><strong>灯り</strong></div></div><button class="primary execute" id="try-spells">接続を確かめ、二つの魔石で試す <span>→</span></button>${result?`<div class="crystal-feedback" role="status">${!result.type.ok?`<strong>型が合いません</strong><p>${result.type.index===2?'出口':`道具 ${result.type.index+1}`} は「${typeNames[result.type.required]}」を受け取りますが、前から来るのは「${typeNames[result.type.received]}」です。つなぎ方を直しましょう。</p>`:`<strong>型は合っています</strong><p>この装置では、入力から出口まで道具が受け取れる種類が一致します。</p><div class="truth-wrap"><table class="truth-table"><caption>二つの魔石での結果</caption><thead><tr><th scope="col">入口</th><th scope="col">道具１の後</th><th scope="col">出口</th><th scope="col">目標</th><th scope="col">結果</th></tr></thead><tbody>${result.results.map(row=>`<tr><th scope="row">${show(row.input)}</th><td>${show(row.trace[1])}</td><td>${show(row.actual)}</td><td>${show(row.expected)}</td><td>${row.correct?'一致':'不一致'}</td></tr>`).join('')}</tbody></table></div>${!complete?'<p>型が合っても、目標とは違う結果になることがあります。道具の働きを見直しましょう。</p>':''}`}</div>`:''}</section>${complete?`<section class="result panel" aria-live="polite"><div class="result-title"><span>✦</span><div><span class="panel-kicker">QUEST COMPLETE</span><h2>二つの魔石で灯りを動かせました！</h2></div></div><p>数と灯りのように、値の種類を型と考えると、道具が受け取れる値と返す値を確かめられます。この依頼では、実行前に接続の型を確認しました。型が合っていても、目的に合う動作をするかは別に確かめる必要があります。</p><p>これは数と灯りだけを使う簡略例です。実際の言語の型規則はさまざまで、この二例の成功はすべての入力での正しさを証明しません。</p>${!storageAvailable?'<p class="storage-warning">進捗を保存できませんでした。ブラウザの保存設定を確認してください。</p>':''}<button class="text-link" id="return">ギルドの依頼へ戻る →</button></section>`:''}<aside class="reference">学びの手がかり：CS2023 <a href="https://ieeecs-media.computer.org/media/education/reports/CS2023.pdf" target="_blank" rel="noopener noreferrer">FPL-Types ↗</a>　｜　入力・出力の型と検査の一例です。</aside></div>`;
  app.querySelector('#back').onclick=renderHome;
