  app.querySelector('#run-tests').onclick=()=>{testing=runTests(testing);writeDraft(active.id,{selected:testing.selected,ran:!!testing.results});if(testingComplete(testing)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderTesting();app.querySelector('#run-tests').focus();};
  if(complete)app.querySelector('#return').onclick=renderHome;
