  app.querySelector('#access-test').onclick=()=>{accessResults=evaluatePolicy(policy);if(accessResults.every(item=>item.correct)){if(!completed.includes(active.id)) completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}else writeDraft(active.id,{policy,tested:true});renderAccess();app.querySelector('.result').scrollIntoView({block:'nearest'});app.querySelector('#return').focus();};
