function renderDelivery() {
  const done=delivery.phase==='done';
  const receivedText=delivery.received.map(id=>fragments[id]).join('');
  app.innerHTML=`<div class="quest-page"><button class="back" id="back">← ギルドに戻る</button><div class="quest-heading"><div><div class="eyebrow"><span></span> QUEST ${active.number} ／ ${active.tag}</div><h1>${active.title}</h1><p>${active.story}</p></div><span class="chapter-badge">嵐の谷 <b>✦</b></span></div><section class="panel delivery-panel"><div class="panel-header"><div><span class="panel-kicker">THE WIND MESSENGER</span><h2>手紙を届ける</h2></div></div>${draftMessage()}<p class="panel-description">手紙は番号順に１つずつ送ります。受け取りの返事が届くまで次は送りません。返事が一定時間届かなければ、同じ番号を再送します。</p><div class="delivery-columns"><div class="delivery-box"><h3>送信者</h3><p>${done?'すべての返事を受け取りました。':`${delivery.current+1}番「${fragments[delivery.current]}」`}</p><span>${done?'配達完了':delivery.phase==='waiting'?'返事を待っています':'送信できます'}</span></div><div class="delivery-arrow" aria-hidden="true">⇄</div><div class="delivery-box"><h3>受信者</h3><p>${receivedText || 'まだ手紙はありません'}</p><span>受信した番号：${delivery.received.length?delivery.received.map(id=>id+1).join('・'):'なし'}</span></div></div>${!done?`<div class="delivery-actions">${delivery.phase==='ready'?'<button class="primary" id="send-letter">手紙を送る <span>→</span></button>':'<button class="primary" id="retry-letter">時間切れを待ち、同じ手紙を再送 <span>↻</span></button>'}</div>`:''}<div class="battle-history" aria-live="polite"><h3>伝令の記録 <small>送信者と受信者の両方の様子</small></h3>${delivery.log.length?`<ol>${delivery.log.map(entry=>`<li><span>${entry.number}番・${entry.attempt}回目</span> ${entry.detail}</li>`).join('')}</ol>`:'<p>最初の手紙を送りましょう。</p>'}</div></section>${done?`<section class="result panel" aria-live="polite"><div class="result-title"><span>✦</span><div><span class="panel-kicker">QUEST COMPLETE</span><h2>手紙が届きました！</h2></div></div><p>送った手紙が消えた場合も、返事だけが消えた場合も、送信者には返事が届きません。時間切れ後に同じ番号を再送し、受信者が重複を除くことで、順番どおりに受け取れました。これは応答を待ってから次を送る方式の簡略化した例です。実際の通信では遅延や誤りなど、ほかにも考えることがあります。</p>${!storageAvailable?'<p class="storage-warning">進捗を保存できませんでした。ブラウザの保存設定を確認してください。</p>':''}<button class="text-link" id="retry-delivery">もう一度届ける ↺</button><br><button class="text-link" id="return">ギルドの依頼へ戻る →</button></section>`:''}<aside class="reference">学びの手がかり：CS2023 <a href="https://ieeecs-media.computer.org/media/education/reports/CS2023.pdf" target="_blank" rel="noopener noreferrer">NC-Reliability ↗</a>　｜　信頼性と再送の一例です。</aside></div>`;
  app.querySelector('#back').onclick=renderHome;
  app.querySelector('#reset-draft').onclick=()=>{clearDraft(active.id);delivery=createDelivery();renderDelivery();app.querySelector('#reset-draft').focus();};
  for(const [id,action] of [['send-letter','send'],['retry-letter','retry']]) {
    const button=app.querySelector(`#${id}`);
    if(button) button.onclick=()=>{delivery=transmit(delivery,action);writeDraft(active.id,delivery.log.map(entry=>entry.attempt===1?'send':'retry'));if(delivery.phase==='done'){if(!completed.includes(active.id)) completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderDelivery();(app.querySelector('#send-letter, #retry-letter')||app.querySelector('#retry-delivery')).focus();};
  }
  if(done){app.querySelector('#retry-delivery').onclick=()=>{delivery=createDelivery();clearDraft(active.id);renderDelivery();app.querySelector('#send-letter').focus();};app.querySelector('#return').onclick=renderHome;}
}
function renderRoutes() {
  const route=routeSearch.status==='found' ? reconstructRoute(routeSearch,'G') : null;
  const available=Object.keys(roads).filter(id=>!routeSearch.settled.includes(id) && routeSearch.distances[id]!==null);
  const roadRows=Object.entries(roads).flatMap(([from,neighbors])=>Object.entries(neighbors).filter(([to])=>from<to).map(([to,weight])=>`<tr><td>${from}（${labels[from]}）</td><td>${to}（${labels[to]}）</td><td>${weight}</td></tr>`)).join('');
  app.innerHTML=`<div class="quest-page"><button class="back" id="back">← ギルドに戻る</button><div class="quest-heading"><div><div class="eyebrow"><span></span> QUEST ${active.number} ／ ${active.tag}</div><h1>${active.title}</h1><p>${active.story}</p></div><span class="chapter-badge">山の街道 <b>✦</b></span></div><section class="panel search-panel"><div class="panel-header"><div><span class="panel-kicker">THE MOUNTAIN ROADS</span><h2>街道の地図</h2></div></div>${draftMessage()}<p class="panel-description">道は双方向です。表の数字は、その道を通る時間を表します。</p><div class="truth-wrap"><table class="truth-table"><caption>道と通過時間</caption><thead><tr><th scope="col">地点</th><th scope="col">地点</th><th scope="col">時間</th></tr></thead><tbody>${roadRows}</tbody></table></div><div class="search-status" aria-live="polite"><strong>${routeSearch.message}</strong><p>確定済み：${routeSearch.settled.length?routeSearch.settled.join(' → '):'まだありません'}</p></div><h3 class="estimate-heading">現在わかっている最短の候補</h3><p class="panel-description">出発地からの候補時間が最も小さい未確定の地点を選びます。選んだ地点から隣に進むことで、より短い候補があれば更新されます。</p><div class="estimate-grid">${Object.keys(roads).map(id=>`<div class="estimate ${routeSearch.settled.includes(id)?'settled':''}"><strong>${id} <small>${labels[id]}</small></strong><span>${routeSearch.distances[id]===null?'未発見':routeSearch.distances[id]+' 時間'}</span><small>${routeSearch.settled.includes(id)?'確定':routeSearch.distances[id]===null?'未発見':'候補'}</small></div>`).join('')}</div>${routeSearch.status==='playing'?`<div class="queue route-queue"><h3>次に確定する地点</h3><div class="queue-buttons">${available.map(id=>`<button data-settle="${id}"><span>${id}</span><small>${routeSearch.distances[id]} 時間</small></button>`).join('')}</div></div>`:''}</section>${route?`<section class="result panel" aria-live="polite"><div class="result-title"><span>✦</span><div><span class="panel-kicker">QUEST COMPLETE</span><h2>早馬が村へ届きました！</h2></div></div><p>最短経路：<strong>${route.join(' → ')}</strong>（合計 ${routeSearch.distances.G} 時間）</p><p>この経路は３本の道を使います。２本の道で行ける S → A → G は７時間なので、道の本数が少なくても所要時間が短いとは限りません。候補時間が最小の地点から確定し、隣の候補を更新する手順はダイクストラ法です。この方法は、道の時間が負ではない場合に使えます。</p>${!storageAvailable?'<p class="storage-warning">進捗を保存できませんでした。ブラウザの保存設定を確認してください。</p>':''}<button class="text-link" id="retry-routes">もう一度探す ↺</button><br><button class="text-link" id="return">ギルドの依頼へ戻る →</button></section>`:''}<aside class="reference">学びの手がかり：CS2023 <a href="https://ieeecs-media.computer.org/media/education/reports/CS2023.pdf" target="_blank" rel="noopener noreferrer">AL-Foundational ↗</a>　｜　重み付き最短路の一例です。</aside></div>`;
  app.querySelector('#back').onclick=renderHome;
  app.querySelector('#reset-draft').onclick=()=>{clearDraft(active.id);routeSearch=createRouteSearch();renderRoutes();app.querySelector('#reset-draft').focus();};
  app.querySelectorAll('[data-settle]').forEach(button=>button.onclick=()=>{routeSearch=settlePlace(routeSearch,button.dataset.settle);writeDraft(active.id,routeSearch.settled);if(routeSearch.status==='found'){if(!completed.includes(active.id)) completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderRoutes();(app.querySelector('[data-settle]')||app.querySelector('#retry-routes')).focus();});
  if(route){app.querySelector('#retry-routes').onclick=()=>{routeSearch=createRouteSearch();clearDraft(active.id);renderRoutes();app.querySelector('[data-settle]').focus();};app.querySelector('#return').onclick=renderHome;}
}
function renderSearch() {
  const positions={S:[30,100],A:[115,50],B:[115,150],C:[210,25],D:[210,100],E:[210,175],F:[305,50],G:[385,140]};
  const edges=Object.entries(paths).flatMap(([from,neighbors])=>neighbors.filter(to=>from<to).map(to=>{const [x1,y1]=positions[from], [x2,y2]=positions[to];return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"/>`;})).join('');
  const nodes=Object.entries(positions).map(([id,[x,y]])=>`<g class="forest-node ${search.explored.includes(id)?'explored':search.seen.includes(id)?'seen':''}"><circle cx="${x}" cy="${y}" r="18"/><text x="${x}" y="${y}" dy=".35em">${id}</text></g>`).join('');
  const route = search.status === 'found' ? routeTo(search,'G') : null;
  app.innerHTML=`<div class="quest-page"><button class="back" id="back">← ギルドに戻る</button><div class="quest-heading"><div><div class="eyebrow"><span></span> QUEST ${active.number} ／ ${active.tag}</div><h1>${active.title}</h1><p>${active.story}</p></div><span class="chapter-badge">霧の森 <b>✦</b></span></div><section class="panel search-panel"><div class="panel-header"><div><span class="panel-kicker">THE MISTY FOREST</span><h2>森の地図</h2></div></div>${draftMessage()}<p class="panel-description">道は双方向で、どの道も長さは同じです。調べた地点の隣で、まだ見つけていない地点を待ち行列の末尾に加えます。同じ地点は二度加えません。</p><svg class="forest-map" viewBox="0 0 415 200" role="img" aria-label="森の地点と双方向の道。各地点のつながりは地図の下にあります。"><g class="forest-edges">${edges}</g>${nodes}</svg><details class="road-list"><summary>地点の名前と道のつながり</summary><ul>${Object.entries(paths).map(([id,neighbors])=>`<li>${id}（${places[id]}）: ${neighbors.join('・')}</li>`).join('')}</ul></details><div class="search-status" aria-live="polite"><strong>${search.message}</strong><p>調査済み：${search.explored.length ? search.explored.join(' → ') : 'まだありません'}</p><p>発見済み：${search.seen.join('・')}</p></div>${search.status==='playing'?`<div class="queue"><h3>待ち行列 <small>先頭 → 末尾</small></h3><p>先頭から地点を選んで調べましょう。</p><div class="queue-buttons">${search.queue.map((id,i)=>`<button data-inspect="${id}" aria-label="${i+1}番目 ${id} ${places[id]} を調べる"><span>${id}</span><small>${places[id]}</small></button>`).join('')}</div></div>`:''}</section>${route?`<section class="result panel" aria-live="polite"><div class="result-title"><span>✦</span><div><span class="panel-kicker">QUEST COMPLETE</span><h2>調査隊を見つけました！</h2></div></div><p>入口からの道：<strong>${route.join(' → ')}</strong>（${route.length-1}本）</p><p>待ち行列の先頭から順番に調べると、入口に近い地点から探索できます。このような方法を幅優先探索といいます。各道の長さが等しいこの森では、発見時の道しるべをたどると道の本数が最も少ない経路になります。</p>${!storageAvailable?'<p class="storage-warning">進捗を保存できませんでした。ブラウザの保存設定を確認してください。</p>':''}<button class="text-link" id="retry-search">もう一度探索する ↺</button><br><button class="text-link" id="return">ギルドの依頼へ戻る →</button></section>`:''}<aside class="reference">学びの手がかり：CS2023 <a href="https://ieeecs-media.computer.org/media/education/reports/CS2023.pdf" target="_blank" rel="noopener noreferrer">AL-Foundational ↗</a>　｜　グラフ探索の一例です。</aside></div>`;
  app.querySelector('#back').onclick=renderHome;
  app.querySelector('#reset-draft').onclick=()=>{clearDraft(active.id);search=createSearch();renderSearch();app.querySelector('#reset-draft').focus();};
  app.querySelectorAll('[data-inspect]').forEach(button=>button.onclick=()=>{search=inspectPlace(search,button.dataset.inspect);writeDraft(active.id,search.explored);if(search.status==='found'){if(!completed.includes(active.id)) completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderSearch();(app.querySelector('[data-inspect]')||app.querySelector('#retry-search')).focus();});
  if(route){app.querySelector('#retry-search').onclick=()=>{search=createSearch();clearDraft(active.id);renderSearch();app.querySelector('[data-inspect]').focus();};app.querySelector('#return').onclick=renderHome;}
}
function renderBattle() {
  const playing = battle.status === 'playing';
  const lights = playing ? lightsForTurn(battle.turn) : null;
  const won = battle.status === 'won';
  app.innerHTML = `<div class="quest-page"><button class="back" id="back">← ギルドに戻る</button><div class="quest-heading"><div><div class="eyebrow"><span></span> QUEST ${active.number} ／ ${active.tag}</div><h1>${active.title}</h1><p>${active.story}</p></div><span class="chapter-badge">灯火の遺跡 <b>✦</b></span></div><section class="panel battle-panel"><div class="panel-header"><div><span class="panel-kicker">THE GUARDIAN</span><h2>灯りが示す隙</h2></div><span class="count">${playing ? battle.turn+1 : battle.turn} / ${MAX_TURNS} ${playing ? '手目' : '手終了'}</span></div>${draftMessage()}<p class="panel-description">守護者は、ふたつの灯りのうち<strong>ちょうど片方が点いている時</strong>だけ攻撃が通ります。それ以外で攻撃すると反撃を受けます。「守る」は反撃を受けずに１手進みます。６手以内に守護者へ２回攻撃を当てましょう。</p><div class="arena"><div class="combatant"><span class="fighter-icon">✧</span><strong>精霊</strong><span>体力 ${battle.playerHealth} / 2</span></div><div class="guardian"><span class="guardian-icon">♜</span><strong>灯火の守護者</strong>${playing?`<div class="lights" aria-label="守護者の灯り：Ａ ${lights[0]?'点灯':'消灯'}、Ｂ ${lights[1]?'点灯':'消灯'}"><span class="light ${lights[0]?'lit':''}">Ａ ${lights[0]?'●':'○'}</span><span class="light ${lights[1]?'lit':''}">Ｂ ${lights[1]?'●':'○'}</span></div>`:'<span class="battle-end-label">戦闘終了</span>'}<span>守り ${battle.guardianHealth} / 2</span></div></div>${playing?'<div class="battle-actions"><button class="primary" id="attack">精霊と攻撃する <span>✦</span></button><button class="secondary" id="guard">守る</button></div>':''}<div class="battle-history" aria-live="polite"><h3>戦いの記録</h3>${battle.history.length?`<ol>${battle.history.map(item=>`<li><span>${item.turn}手目 ／ Ａ${item.a}・Ｂ${item.b}</span> ${item.message}</li>`).join('')}</ol>`:'<p>灯りを見て行動を選びましょう。</p>'}</div></section>${!playing?`<section class="result panel" aria-live="polite"><div class="result-title"><span>${won?'✦':'↻'}</span><div><span class="panel-kicker">${won?'QUEST COMPLETE':'TRY AGAIN'}</span><h2>${won?'守護者が道を開きました！':'精霊が力を使い果たしました'}</h2></div></div><p>${won?'守護者は微笑み、門を開きました。片方だけが点灯する状態は、灯火の門でも扱う排他的論理和（XOR）と同じ条件です。':'灯りが同じなら守り、片方だけなら攻撃しましょう。もう一度試せます。'}</p>${won&&!storageAvailable?'<p class="storage-warning">進捗を保存できませんでした。ブラウザの保存設定を確認してください。</p>':''}<button class="text-link" id="retry">もう一度挑む ↺</button><br><button class="text-link" id="return">ギルドの依頼へ戻る →</button></section>`:''}<aside class="reference">学びの手がかり：CS2023 <a href="https://ieeecs-media.computer.org/media/education/reports/CS2023.pdf" target="_blank" rel="noopener noreferrer">AR-Logic ↗</a>　｜　論理条件を観察して行動を選ぶ応用です。</aside></div>`;
  app.querySelector('#back').onclick=renderHome;
  app.querySelector('#reset-draft').onclick=()=>{clearDraft(active.id);battle=createBattle();renderBattle();app.querySelector('#reset-draft').focus();};
  for (const action of ['attack','guard']) {
    const button=app.querySelector(`#${action}`);
    if(button) button.onclick=()=>{battle=takeTurn(battle,action);writeDraft(active.id,battle.history.map(item=>item.action));if(battle.status==='won'){if(!completed.includes(active.id)) completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderBattle();(app.querySelector(`#${action}`)||app.querySelector('#retry')).focus();};
  }
  if(!playing){app.querySelector('#retry').onclick=()=>{battle=createBattle();clearDraft(active.id);renderBattle();app.querySelector('#attack').focus();};app.querySelector('#return').onclick=renderHome;}
}
function renderCircuit() {
  const success = circuitRows && circuitRows.every(row => row.correct);
  const selectGate = (index, label) => `<label class="gate-choice">${label}<select data-gate="${index}">${Object.entries(gates).map(([id, gate])=>`<option value="${id}" ${circuitParts[index]===id?'selected':''}>${gate.label}</option>`).join('')}</select><small>${gates[circuitParts[index]].description}</small></label>`;
  app.innerHTML = `<div class="quest-page"><button class="back" id="back">← ギルドに戻る</button><div class="quest-heading"><div><div class="eyebrow"><span></span> QUEST ${active.number} ／ ${active.tag}</div><h1>${active.title}</h1><p>${active.story}</p></div><span class="chapter-badge">灯火の遺跡 <b>✦</b></span></div><section class="panel circuit-panel"><div class="panel-header"><div><span class="panel-kicker">THE LANTERN GATE</span><h2>灯火の回路を組もう</h2></div></div>${draftMessage()}<p class="panel-description">０は消灯、１は点灯です。灯火ＡとＢの信号は、上と下の両方の部品に届きます。上と下の出力を、最後の「両方」部品に渡します。</p><div class="circuit-layout"><div class="circuit-input">灯火 Ａ<br>灯火 Ｂ</div><div class="circuit-arrow" aria-hidden="true">→</div><div class="gate-stack">${selectGate(0,'上の部品')}${selectGate(1,'下の部品')}</div><div class="circuit-arrow" aria-hidden="true">→</div><div class="final-gate">両方<br><small>AND</small></div><div class="circuit-arrow" aria-hidden="true">→</div><div class="circuit-input">門</div></div><button id="circuit-test" class="primary execute">４通りの灯火で試す <span>→</span></button><button id="hint" class="hint-button" aria-expanded="${hintOpen}">✧ ヒント ${hintOpen?'を閉じる':'を見る'}</button>${hintOpen?'<p class="hint-text">片方だけが１のときは「少なくとも一方が１」であり、かつ「両方が１ではない」状態です。</p>':''}</section>${circuitRows?`<section class="result panel" aria-live="polite"><div class="result-title"><span>${success?'✦':'↻'}</span><div><span class="panel-kicker">${success?'QUEST COMPLETE':'TRY AGAIN'}</span><h2>${success?'灯火の門が開きました！':'まだ開かない組み合わせがあります'}</h2></div></div><p>${success?'この回路は、どちらか片方だけが１のときに１を出します。この動作を排他的論理和（XOR）といいます。':'目標と実際を見比べ、部品を選び直してもう一度試しましょう。'}</p><div class="truth-wrap"><table class="truth-table"><caption>４通りの試験結果（１は点灯または開く）</caption><thead><tr><th scope="col">Ａ</th><th scope="col">Ｂ</th><th scope="col">上</th><th scope="col">下</th><th scope="col">目標</th><th scope="col">実際</th><th scope="col">判定</th></tr></thead><tbody>${circuitRows.map(row=>`<tr><td>${row.a}</td><td>${row.b}</td><td>${row.upper}</td><td>${row.lower}</td><td>${row.expected}</td><td>${row.actual}</td><td>${row.correct?'一致':'不一致'}</td></tr>`).join('')}</tbody></table></div>${success&&!storageAvailable?'<p class="storage-warning">進捗を保存できませんでした。ブラウザの保存設定を確認してください。</p>':''}<button class="text-link" id="return">ギルドの依頼へ戻る →</button></section>`:''}<aside class="reference">学びの手がかり：CS2023 <a href="https://ieeecs-media.computer.org/media/education/reports/CS2023.pdf" target="_blank" rel="noopener noreferrer">AR-Logic ↗</a>　｜　この依頼は組合せ回路の一部を扱います。</aside></div>`;
  app.querySelector('#back').onclick=renderHome;
  app.querySelector('#reset-draft').onclick=()=>{clearDraft(active.id);circuitParts=['AND','AND'];circuitRows=null;hintOpen=false;renderCircuit();app.querySelector('#reset-draft').focus();};
  app.querySelectorAll('[data-gate]').forEach(select=>select.onchange=()=>{const index=Number(select.dataset.gate); circuitParts[index]=select.value; circuitRows=null;writeDraft(active.id,{parts:circuitParts,tested:false}); renderCircuit(); app.querySelector(`[data-gate="${index}"]`).focus();});
  app.querySelector('#hint').onclick=()=>{hintOpen=!hintOpen;renderCircuit();app.querySelector('#hint').focus();};
  app.querySelector('#circuit-test').onclick=()=>{circuitRows=evaluateCircuit(...circuitParts); if(circuitRows.every(row=>row.correct)){if(!completed.includes(active.id)) completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}else writeDraft(active.id,{parts:circuitParts,tested:true});renderCircuit();app.querySelector('.result').scrollIntoView({block:'nearest'});app.querySelector('#return').focus();};
  if(circuitRows) app.querySelector('#return').onclick=renderHome;
}
function renderSorting() {
  const done = isSorted(stones);
  app.innerHTML = `<div class="quest-page"><button class="back" id="back">← ギルドに戻る</button><div class="quest-heading"><div><div class="eyebrow"><span></span> QUEST ${active.number} ／ アルゴリズムの基礎</div><h1>${active.title}</h1><p>${active.story}</p></div><span class="chapter-badge">古代の祭壇 <b>✦</b></span></div><section class="panel sorting-panel"><div class="panel-header"><div><span class="panel-kicker">THE ANCIENT ALTAR</span><h2>魔石を小さい順に</h2></div><span class="count">入れ替え ${swapCount} 回</span></div>${draftMessage()}<p class="panel-description">となり合う２つの魔石の間にある矢印を選ぶと、位置が入れ替わります。</p><div class="stones" aria-label="魔石の並び">${stones.map((stone, i) => `<span class="stone" aria-label="${i+1}番目は${stone}">${stone}</span>${i < stones.length-1 ? `<button class="swap" data-swap="${i}" aria-label="${stone}と${stones[i+1]}を入れ替える">⇄</button>` : ''}`).join('')}</div><div class="sorting-actions"><button class="hint-button" id="hint" aria-expanded="${hintOpen}">✧ ヒント ${hintOpen ? 'を閉じる' : 'を見る'}</button></div>${hintOpen ? '<p class="hint-text">左から隣り合う数字を比べ、左が大きければ入れ替えてみましょう。何度か繰り返すと、少しずつ整います。</p>' : ''}</section>${done ? `<section class="result panel" aria-live="polite"><div class="result-title"><span>✦</span><div><span class="panel-kicker">QUEST COMPLETE</span><h2>祭壇に光が戻りました！</h2></div></div><p>隣り合う魔石を比較して入れ替える操作は、整列アルゴリズムの基本になります。最初の並びには、大きい数が小さい数より前にある組が５組あります。隣同士を一度入れ替えると、この数は１だけ変わるため、この並びを整えるには少なくとも５回の入れ替えが必要です。今回は ${swapCount} 回でした。</p>${!storageAvailable ? '<p class="storage-warning">進捗を保存できませんでした。ブラウザの保存設定を確認してください。</p>' : ''}<button class="text-link" id="return">ギルドの依頼へ戻る →</button></section>` : ''}<aside class="reference">学びの手がかり：CS2023 <a href="https://ieeecs-media.computer.org/media/education/reports/CS2023.pdf" target="_blank" rel="noopener noreferrer">AL-Foundational / SDF-Algorithms ↗</a>　｜　この依頼は整列の一部を扱います。</aside></div>`;
  app.querySelector('#back').onclick = renderHome;
  app.querySelector('#hint').onclick = () => { hintOpen = !hintOpen; renderSorting(); app.querySelector('#hint').focus(); };
  app.querySelector('#reset-draft').onclick = () => { clearDraft(active.id);stones = active.initial.slice(); swapCount = 0;hintOpen=false;renderSorting(); app.querySelector('#reset-draft').focus(); };
  app.querySelectorAll('[data-swap]').forEach(button => button.onclick = () => {
    const index = Number(button.dataset.swap);
    stones = swapAdjacent(stones, index); swapCount++;
    if (isSorted(stones)) { if (!completed.includes(active.id)) completed.push(active.id); save();if(storageAvailable)clearDraft(active.id); } else writeDraft(active.id,{values:stones,count:swapCount});
    renderSorting();
    app.querySelector(`[data-swap="${index}"]`).focus();
  });
  if (done) app.querySelector('#return').onclick = renderHome;
}
function workshopDraft(){return {program,scenario:scenarioIndex,executed:result!==null};}
function renderQuest() {
  const l=active;
  const scenario = l.scenarios?.[scenarioIndex];
  const view = { ...l, ...scenario };
  const trace = result?.cases[scenarioIndex].trace;
  const current=trace ? trace[frame] : {x:view.start[0],y:view.start[1],direction:view.direction};
  const cells=[];
  for (let y=0;y<l.rows;y++) for(let x=0;x<l.cols;x++) {
    const wall=view.walls.some(([wx,wy])=>wx===x&&wy===y), goal=view.goal[0]===x&&view.goal[1]===y, spirit=current.x===x&&current.y===y;
    cells.push(`<div class="tile ${wall?'wall':''} ${goal?'goal':''}" role="gridcell" aria-label="${x+1}列 ${y+1}行 ${wall?'壁':goal?'目的地':'道'}${spirit?'、精霊、'+['上','右','下','左'][current.direction]+'向き':''}">${wall?'':goal?'<span class="goal-symbol">✦</span>':''}${spirit?`<span class="spirit" aria-hidden="true">${['↑','→','↓','←'][current.direction]}</span>`:''}</div>`);
  }
  app.innerHTML=`<div class="quest-page"><button class="back" id="back">← ギルドに戻る</button><div class="quest-heading"><div><div class="eyebrow"><span></span> QUEST ${l.number} ／ ${l.tag}</div><h1>${l.title}</h1><p>${l.story}</p></div><span class="chapter-badge">精霊の工房 <b>✦</b></span></div><div class="play-layout"><section class="map-panel panel"><div class="panel-header"><div><span class="panel-kicker">THE WORKSHOP</span><h2>精霊の通り道</h2></div><span class="legend">✦ 灯りのかけら</span></div>${l.scenarios?`<div class="scenario-selector" role="group" aria-label="試す道を選択">${l.scenarios.map((item,i)=>`<button data-scenario="${i}" aria-pressed="${i===scenarioIndex}">${item.name}${result ? (result.cases[i].success?' ✓':' ✕') : ''}</button>`).join('')}</div><p class="scenario-explanation">同じ命令を両方の道で試します。道の名前を選ぶと地図を切り替えられます。</p>`:''}<div class="map-wrap"><div class="map-grid" role="grid" aria-label="精霊の通り道" style="--cols:${l.cols}">${cells.join('')}</div></div><div class="map-bottom"><span>✦　精霊は矢印の方向を向いています</span><span>${l.cols} × ${l.rows} の地図</span></div></section><section class="command-panel panel"><div class="panel-header"><div><span class="panel-kicker">YOUR INSTRUCTIONS</span><h2>精霊へのおねがい</h2></div><span class="count">${program.length} <small>/ ${l.max}</small></span></div>${draftMessage()}<p class="panel-description">命令を選んで上から順に並べよう。</p><div class="program" aria-label="命令の順番">${program.length?program.map((id,i)=>`<div class="command-row"><span class="step-no">${String(i+1).padStart(2,'0')}</span><span class="command-icon">${commands[id].icon}</span><span class="command-name">${commands[id].label}</span><button class="remove" data-remove="${i}" aria-label="${i+1}番目の${commands[id].label}を削除">×</button></div>`).join(''):'<div class="empty">ここに命令を並べましょう <span>↓</span></div>'}</div><p class="palette-title">命令を追加 <span>／ 選ぶと末尾に加わります</span></p><div class="palette">${l.available.map(id=>`<button data-command="${id}" ${program.length>=l.max?'disabled':''} title="${commands[id].description}"><span>${commands[id].icon}</span>${commands[id].label} <b>＋</b></button>`).join('')}</div><button id="execute" class="primary execute" ${program.length?'':'disabled'}>命令を実行する <span>→</span></button><button id="hint" class="hint-button" aria-expanded="${hintOpen}">✧ ヒント ${hintOpen?'を閉じる':'を見る'}</button>${hintOpen?`<p class="hint-text">${l.hint}</p>`:''}</section></div>${result?`<section class="result panel" aria-live="polite"><div class="result-title"><span>${result.success?'✦':'↻'}</span><div><span class="panel-kicker">${result.success?'QUEST COMPLETE':'TRY AGAIN'}</span><h2>${result.success?'灯りを届けました！':'もう一度、道順を考えよう'}</h2></div></div><p>${result.success?l.lesson:'下の記録で精霊の動きを確認し、命令を変えて再挑戦できます。'+(l.scenarios?' 両方の道で届く命令を考えましょう。':'')}</p><div class="trace"><button id="previous" ${frame===0?'disabled':''}>← 前の動き</button><span>${frame} / ${trace.length-1}　${trace[frame].message}</span><button id="next" ${frame===trace.length-1?'disabled':''}>次の動き →</button></div>${!storageAvailable?'<p class="storage-warning">進捗を保存できませんでした。ブラウザの保存設定を確認してください。</p>':''}<button class="text-link" id="return">ギルドの依頼へ戻る →</button></section>`:''}<aside class="reference">学びの手がかり：CS2023 <a href="https://ieeecs-media.computer.org/media/education/reports/CS2023.pdf" target="_blank" rel="noopener noreferrer">SDF-Fundamentals ↗</a>　｜　この依頼はプログラミング基礎の一部を扱います。</aside></div>`;
  app.querySelector('#back').onclick=renderHome;
  app.querySelector('#reset-draft').onclick=()=>{clearDraft(l.id);program=[];scenarioIndex=0;result=null;frame=0;hintOpen=false;renderQuest();app.querySelector('#reset-draft').focus();};
  app.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{scenarioIndex=Number(b.dataset.scenario); frame=result ? result.cases[scenarioIndex].trace.length-1 : 0; writeDraft(l.id,workshopDraft());renderQuest(); app.querySelector(`[data-scenario="${scenarioIndex}"]`).focus();});
  app.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>{ const id=b.dataset.command; program.push(id); result=null;writeDraft(l.id,workshopDraft()); renderQuest(); (app.querySelector(`[data-command="${id}"]:not(:disabled)`) || app.querySelector('#execute')).focus(); });
  app.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const index=Number(b.dataset.remove); program.splice(index,1); result=null;writeDraft(l.id,workshopDraft()); renderQuest(); (app.querySelector(`[data-remove="${Math.min(index,program.length-1)}"]`) || app.querySelector('[data-command]')).focus();});
  app.querySelector('#hint').onclick=()=>{hintOpen=!hintOpen;renderQuest();app.querySelector('#hint').focus();};
  app.querySelector('#execute').onclick=()=>{result=runScenarios(l,program);frame=result.cases[scenarioIndex].trace.length-1;if(result.success){if(!completed.includes(l.id)) completed.push(l.id);save();if(storageAvailable)clearDraft(l.id);}else writeDraft(l.id,workshopDraft());renderQuest();app.querySelector('.result').scrollIntoView({block:'nearest'});app.querySelector('#previous:not(:disabled), #return').focus();};
  if(result){ app.querySelector('#previous').onclick=()=>{frame--;renderQuest();(app.querySelector('#previous:not(:disabled)')||app.querySelector('#next')).focus();}; app.querySelector('#next').onclick=()=>{frame++;renderQuest();(app.querySelector('#next:not(:disabled)')||app.querySelector('#previous')).focus();}; app.querySelector('#return').onclick=renderHome; }
}
renderHome();
